      async renameImportedCourse(courseId,newTitle){const id=String(courseId||'');const title=String(newTitle||'').trim().replace(/\s+/g,' ');if(!title)return {ok:false,error:'Le nom du parcours ne peut pas être vide.'};if(title.length>120)return {ok:false,error:'Le nom du parcours est limité à 120 caractères.'};const index=this.imported.findIndex(c=>courseIdFromContent(c)===id);if(index<0)return {ok:false,error:'Seuls les parcours importés peuvent être renommés.'};const conflict=this.allCourses().some(c=>String(c.title||'').trim().toLocaleLowerCase('fr')===title.toLocaleLowerCase('fr')&&courseIdFromContent(c)!==id);if(conflict)return {ok:false,error:'Un autre parcours porte déjà ce nom.'};const before=deepClone(this.imported[index]);const next=deepClone(before);next.localCourseId=id;next.title=title;next.renamedAt=nowIso();next.originalImportedTitle=next.originalImportedTitle||before.importOriginalTitle||before.title;this.imported[index]=next;const cacheWritten=this.saveImportedCourses({allowFailure:true});const cacheOk=cacheWritten&&storage.report().mode==='localStorage';this.load();const persisted=await this.scheduleDurableCommit('rename');const durable=!!(persisted&&persisted.ok);if(!durable&&!cacheOk){this.imported[index]=before;this.saveImportedCourses({allowFailure:true});this.load();return {ok:false,error:'Renommage non enregistré : aucun stockage persistant disponible.'};}this.journal.record('imported_course_renamed',{courseId:id,from:before.title,to:title,cacheOk,cacheWritten,durable});return {ok:true,courseId:id,title,cacheOk,cacheWritten,durable,warning:durable?'':'IndexedDB indisponible : renommage conservé par le stockage local du navigateur.'};}
      async renameImportedCollection(collectionKey,newTitle){const key=String(collectionKey||'');const packageId=key.startsWith('import:')?key.slice(7):key;const title=String(newTitle||'').trim().replace(/\s+/g,' ');if(!packageId)return {ok:false,error:'Plan importé introuvable.'};if(!title)return {ok:false,error:'Le nom du plan ne peut pas être vide.'};if(title.length>120)return {ok:false,error:'Le nom du plan est limité à 120 caractères.'};const indexes=[];for(let i=0;i<this.imported.length;i++){if(String(this.imported[i]&&this.imported[i].importPackageId||'')===packageId)indexes.push(i);}if(!indexes.length)return {ok:false,error:'Seuls les plans importés peuvent être renommés.'};const normalized=title.toLocaleLowerCase('fr');const model=window.LearnItCourseCollectionModel;const conflictPackages=new Map();for(const course of this.imported){const otherPackage=String(course&&course.importPackageId||'');if(!otherPackage||otherPackage===packageId||conflictPackages.has(otherPackage))continue;const fallback=model&&typeof model.humanizePackageLabel==='function'?model.humanizePackageLabel(otherPackage):otherPackage;conflictPackages.set(otherPackage,String(course.importCollectionTitle||fallback||'').trim().toLocaleLowerCase('fr'));}if([...conflictPackages.values()].includes(normalized))return {ok:false,error:'Un autre plan porte déjà ce nom.'};const before=indexes.map(index=>({index,course:deepClone(this.imported[index])}));const renamedAt=nowIso();for(const index of indexes){const next=deepClone(this.imported[index]);const fallback=model&&typeof model.humanizePackageLabel==='function'?model.humanizePackageLabel(packageId):packageId;next.importCollectionTitle=title;next.collectionRenamedAt=renamedAt;next.originalImportCollectionTitle=next.originalImportCollectionTitle||next.importCollectionTitleSource||fallback;this.imported[index]=next;}const cacheWritten=this.saveImportedCourses({allowFailure:true});const cacheOk=cacheWritten&&storage.report().mode==='localStorage';this.load();const persisted=await this.scheduleDurableCommit('collection-rename');const durable=!!(persisted&&persisted.ok);if(!durable&&!cacheOk){for(const row of before)this.imported[row.index]=row.course;this.saveImportedCourses({allowFailure:true});this.load();return {ok:false,error:'Renommage du plan non enregistré : aucun stockage persistant disponible.'};}this.journal.record('imported_collection_renamed',{collectionKey:'import:'+packageId,packageId,to:title,courseCount:indexes.length,cacheOk,cacheWritten,durable});return {ok:true,collectionKey:'import:'+packageId,packageId,title,courseCount:indexes.length,cacheOk,cacheWritten,durable,warning:durable?'':'IndexedDB indisponible : renommage conservé par le stockage local du navigateur.'};}
      loadImportHistory(){try{const value=JSON.parse(storage.getItem(IMPORT_HISTORY_KEY)||'[]');return Array.isArray(value)?value.slice(-10):[]}catch(e){return [];}}
